const staticData = $getWorkflowStaticData('global');
if (!staticData.chats || typeof staticData.chats !== 'object') {
  staticData.chats = {};
}
const body = $('Webhook').first().json.body || {};
const message = body.message || {};
const hasChat = !!(message.chat && message.chat.id != null && message.chat.id !== '');
const chatId = hasChat ? String(message.chat.id) : '';
const text = String(message.text != null ? message.text : '');
const system = 'You are a helpful assistant chatting with a user on Telegram.\n- Answer clearly and briefly. Keep replies under 150 words unless asked for more.\n- Reply in the same language the user writes in.\n- Use plain text. Do not use Markdown tables or long headings.\n- If you do not know something, say so. Do not invent facts.\n- Do not give medical, legal or financial advice as certain fact.';
let history;
if (!hasChat) {
  history = [{ role: 'user', content: text }];
} else {
  const prior = Array.isArray(staticData.chats[chatId]) ? staticData.chats[chatId] : [];
  history = prior.slice(-9);
  history.push({ role: 'user', content: text });
  staticData.chats[chatId] = history.slice(-10);
  history = staticData.chats[chatId];
}
return [{ json: { messages: [{ role: 'system', content: system }].concat(history) } }];

const item = Object.assign({}, $input.first().json);
const choice = item.choices && item.choices[0] && item.choices[0].message;
const reply = String((choice && choice.content) || '');
item.output = reply;
const staticData = $getWorkflowStaticData('global');
if (!staticData.chats || typeof staticData.chats !== 'object') {
  staticData.chats = {};
}
const body = $('Webhook').first().json.body || {};
const message = body.message || {};
const hasChat = !!(message.chat && message.chat.id != null && message.chat.id !== '');
if (hasChat) {
  const chatId = String(message.chat.id);
  const prior = Array.isArray(staticData.chats[chatId]) ? staticData.chats[chatId] : [];
  prior.push({ role: 'assistant', content: reply });
  staticData.chats[chatId] = prior.slice(-10);
}
return [{ json: item }];
